interior_fill2 = []
for r in range(11):
    row = []
    for c in range(12):
        # Border: row 0, row 10, col 0, col 11 stay as 3s
        if r == 0 or r == 10 or c == 0 or c == 11:
            row.append(3)
        # Interior: replace 1s with 2s, preserve 3s from floating segment
        elif r in [1, 3, 4, 5] and c == 3:
            # These rows have floating segment 3s at col 3
            row.append(3)
        else:
            # All other interior cells become 2
            row.append(2)
    interior_fill2.append(row)

print("Interior fill preserving floating segment:")
for row in interior_fill2:
    print(row)

